package foodchain

import (
	"fmt"
	"strings"
)

var animals = []string{
	"fly",
	"spider",
	"bird",
	"cat",
	"dog",
	"goat",
	"cow",
	"horse",
}

var comments = []string{
	"", // fly
	"It wriggled and jiggled and tickled inside her.",
	"How absurd to swallow a bird!",
	"Imagine that, to swallow a cat!",
	"What a hog, to swallow a dog!",
	"Just opened her throat and swallowed a goat!",
	"I don't know how she swallowed a cow!",
	"She's dead, of course!",
}

func Verse(v int) string {
	var b strings.Builder

	fmt.Fprintf(&b, "I know an old lady who swallowed a %s.\n", animals[v-1])
	fmt.Fprintf(&b, "%s\n", comments[v-1])

	if v < len(animals) {
		for i := v - 2; i >= 0; i-- {
			if i == 1 {
				fmt.Fprintf(&b, "She swallowed the %s to catch the %s that wriggled and jiggled and tickled inside her.\n", animals[v-1], animals[i])
			} else {
				fmt.Fprintf(&b, "She swallowed the %s to catch the %s.\n", animals[v-1], animals[i])
			}
		}
		fmt.Fprintf(&b, "I don't know why she swallowed the fly. Perhaps she'll die.")
	}

	return b.String()
}

func Verses(start, end int) string {
	verses := make([]string, 0, end-start+1)
	for v := start; v <= end; v++ {
		verses = append(verses, Verse(v))
	}
	return strings.Join(verses, "\n\n")
}

func Song() string {
	return Verses(1, len(animals))
}

