	"What a hog, to swallow a dog!",
	"Just opened her throat and swallowed a goat!",
	"I don't know how she swallowed a cow!",
	"She's dead, of course!",
}

func Verse(v int) string {
	lines := []string{
		fmt.Sprintf("I know an old lady who swallowed a %s.", animals[v-1]),
	}

	if comments[v-1] != "" {
		lines = append(lines, comments[v-1])
	}

	if v < len(animals) {
		for i := v - 2; i >= 0; i-- {
			if i == 1 {
				lines = append(lines, fmt.Sprintf("She swallowed the %s to catch the %s that wriggled and jiggled and tickled inside her.", animals[i+1], animals[i]))
			} else {
				lines = append(lines, fmt.Sprintf("She swallowed the %s to catch the %s.", animals[i+1], animals[i]))
			}
		}
		lines = append(lines, "I don't know why she swallowed the fly. Perhaps she'll die.")
	}

	return strings.Join(lines, "\n")
}

